// UI icons: Tabler Icons (MIT, https://github.com/tabler/tabler-icons), the subset in
// ./tabler/icons.generated.ts generated by `npm run ui-icons` from the pinned @tabler/icons
// package. Decorative: always paired with an accessible label on the control that uses them.
// (File/folder icons in the explorer and AI agent logos have their own sets.)
import { createElement } from 'react';
import { ICONS } from './tabler/icons.generated';

export type IconName = keyof typeof ICONS;

export function Icon({ name, size = 16, className }: { name: IconName; size?: number; className?: string }) {
  const icon = ICONS[name];
  return (
    <svg
      className={className}
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill={icon.filled ? 'currentColor' : 'none'}
      stroke={icon.filled ? 'none' : 'currentColor'}
      // Tabler's default is 2; 1.75 keeps the 10-16 px icons as light as the app's text.
      strokeWidth={1.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
    >
      {icon.nodes.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs }))}
    </svg>
  );
}
